def slug(value):
    value = unicodedata.normalize('NFD', value.replace('ı', 'i').replace('İ', 'I'))
    value = ''.join(c for c in value if unicodedata.category(c) != 'Mn').lower()
    return re.sub('[^a-z0-9]+', '-', value).strip('-')[:200]


def html(sections):
    return ''.join('<h2>' + title + '</h2><p>' + body + '</p>' for title, body in sections)


